                onContentReady() {
                    var that = this;
                    Gordic.Eko.Utils.ShowEkoBookStateFlash(this, this.AktSubrady);
                    this.NastavTlacitka();
                    this.preevidenceData.pripad = true;
                    this.title = "jres:26600152" + " (" + this.detailDto.ac_ag?.trim() + ")"; //RC 26600152 : Veřejná zakázka
                    this.findFields().gfield("model", "apply", this.detailDto, { setFlags: { valid: false } });
                    Gordic.PopisneVlastnosti.applyValues(that, this.detailDto["vlastnosti"] ?? {});
                    this.kpis.kpiCelkemBlokovano.secondaryText = Gordic.Templates.Formatters.number(this.kpiData[0], "C").toString() + " " + this.kpis.kpiCelkemBlokovano.unit;
                    this.kpis.kpiPocetSubjektu.secondaryText = Gordic.Templates.Formatters.number(this.detailDto.evzsesuCount);
                    this.kpis.kpiProcentoNasmlouvanosti.chart =
                        {
                            data: parseDecimal(this.kpiData[1]),
                            value: parseDecimal(this.kpiData[1]),
                            type: "liquid"
                        };
                    this.kpis.kpiProcentoNasmlouvanosti.secondaryText = "jres:26600680".replace("{0}", this.kpiData[1].toString()); //RC 26600680 : Procento nasmlouvanosti
                    this.kpis.update(); //update všech kpi
                }
