                //---------------------------------------------------------------------
                NastavTlacitka() {
                    this.actions.schvaleniAkce.update({ enabled: this.detailDto.s_vz != 10 && this.ac.schvaleni && !this.readOnly });
                    this.actions.schvaleniZrusitAkce.update({ enabled: (this.detailDto.s_vz == 10 || this.detailDto.s_vz == 40) && this.ac.schvaleni_zrus && !this.readOnly });
                    this.actions.ukonceniAkce.update({ enabled: this.detailDto.s_vz != 50 && this.ac.ukonceni && !this.readOnly });
                    this.actions.ukonceniZrusitAkce.update({ enabled: this.detailDto.s_vz == 50 && this.ac.ukonceni_zrus && !this.readOnly });
                    this.actions.kategorieAkce.update({
                        enabled: !this.readOnly && this.detailDto.cis_zakon > 40 ||
                            (this.detailDto.cis_zakon == 40 && (this.detailDto.soutez == "§138" || this.detailDto.soutez == "§138 kat."))
                    });
                }
                //---------------------------------------------------------------------
                NastavTlacitkaPoZmeneAc() {
                    this.actions.profilFinancovaniAkce.update({ enabled: this.ac.vprc });
                    this.actions.financovaniAkce.update({ enabled: this.ac.financovani });
                    this.actions.soutezeAkce.update({ enabled: this.ac.souteze });
                    this.actions.klicovaSlovaAkce.update({ enabled: this.ac.klicova_slova });
                    this.actions.navrhyAkce.update({ enabled: this.ac.generuj_sml });
                    this.actions.formulareAkce.update({ enabled: this.ac.formulare });
                    this.actions.castiVZAkce.update({ enabled: this.ac.casti });
                    this.actions.komodityAkce.update({ enabled: this.ac.komodity });
                    this.actions.dokumentyAkce.update({ enabled: this.ac.dokumenty });
                    this.actions.listDPAkce.update({ enabled: this.ac.list });
                    this.actions.plneniAkce.update({ enabled: this.ac.cena });
                    this.actions.epkAkce.update({ enabled: this.ac.epk });
                    this.actions.tiskAkce.update({ enabled: this.ac.tisk });
                    this.actions.uvolneniAkce.update({ enabled: this.ac.uvolneni });
                    this.actions.predaniAkce.update({ enabled: this.ac.predani });
                    this.actions.prideleniAkce.update({ enabled: this.ac.prideleni });
                    this.actions.prevzetiAkce.update({ enabled: this.ac.prevzeti });
                    this.actions.nadlimAkce.update({ enabled: this.ac.navazat_nadlim });
                    this.actions.predAkce.update({ enabled: this.ac.pred_ozn });
                    this.NastavTlacitka();
                }
                //---------------------------------------------------------------------
                akceUkonceni() {
                    var that = this;
                    var otazka = "jres:26600275"; //RC 26600275 : Opravdu chcete ukončit VZ?;;Po ukončení budou znemožněny jakékoliv manipulace s případem!
                    this.dotaz(otazka)
                        .then(() => {
                        var odp = [0, 0, 0];
                        var stru = {
                            seznam: that.vratData(), akce: "ukonceni", param: 200, odpoved: odp
                        };
                        that.isl.PapUkonceni.ukonceni(stru).get().then(function (retVal) {
                            var def = $.Deferred();
                            if (retVal.data.dotaz != "") { // dotaz, co dělat když jsou nenavázané prostředky
                                var def0 = $.Deferred();
                                that.dotaz(retVal.data.dotaz)
                                    .then(() => {
                                    stru.odpoved[0] = 1;
                                    that.isl.PapUkonceni.ukonceni(stru).get().then(function (retVal) {
                                        var def1 = $.Deferred();
                                        if (retVal.data.dotaz != "") { // dotaz, zda uvolnit prostředky
                                            that.dotaz(retVal.data.dotaz)
                                                .then(() => {
                                                stru.odpoved[1] = 1;
                                                that.dotaz(retVal.data.hlas) // dotaz zda upravit částku
                                                    .then(() => {
                                                    stru.odpoved[2] = 1;
                                                    def1.resolve();
                                                })
                                                    .fail(() => {
                                                    stru.odpoved[2] = -1;
                                                    def1.resolve();
                                                });
                                            })
                                                .fail(() => {
                                                stru.odpoved[1] = -1;
                                                def1.resolve();
                                            });
                                        }
                                        def1.then(function () {
                                            that.isl.PapUkonceni.ukonceni(stru).get().then(function (retVal) {
                                                def0.resolve(retVal.data);
                                            });
                                        });
                                    });
                                })
                                    .fail(function () { def0.reject(); }); // nevzkračuji - nanavázané prostředky
                                def0.then(function (retVal) {
                                    def.resolve(retVal);
                                });
                                def0.fail(function () { def.reject(); });
                            }
                            else
                                def.resolve(retVal.data);
                            def.then(function (retVal) {
                                if (retVal.hlas != "") {
                                    that.dialogs.warning("jres:26600274", retVal.hlas); //RC 26600276 : Upozornění
                                }
                                if (retVal.ok) {
                                    that.NactiData();
                                    that.isChanged = true;
                                }
                            });
                        });
                    });
                }
