                        //        that.dialogs.warning("jres:26600274", "jres:26600481".replace("{0}", that.data.parametry!.c_preblok!.toString())); //RC 26600481 : Částka nesmí být vyšší, než byly přednastavené prostředky.;;Hodnota přednastavených prostředků: {0}
                        //        that.findForms("FormOstUdaje").findFields("c_preblok").gfield("setValue", that.data.parametry!.c_preblok!);
                        //        that.findForms("FormOstUdaje").findFields("c_preblok").find("input").focus();
                        //        return $.Deferred().reject();
