                //---------------------------------------------------------------------
                function NaplnDisable(vl_soutez, vl_priz_dzr, vl_nadTyp, pole_s, pole_p) {
                    var disable = [false, false, false, false, false];
                    if (vl_soutez == "§10 odst.2 písm. a)" || vl_soutez == "§21 odst.1 písm. a)" || vl_soutez == "§56" || vl_priz_dzr == "a" || vl_soutez == "§21 odst.1 písm. f)" || vl_nadTyp == 8 || vl_soutez == "§53") {
                        disable = [false, true, false, true, false];
                    }
                    if (vl_soutez == "§10 odst.2 písm. b)" || vl_soutez == "§21 odst.1 písm. b)" || vl_soutez == "§58" || vl_priz_dzr == "b")
                        disable = [false, false, false, true, false];
                    if (vl_soutez == "§10 odst.2 písm. c)" || vl_soutez == "§21 odst.1 písm. c)" || vl_soutez == "§60" || vl_priz_dzr == "c" || vl_soutez == "§21 odst.1 písm. e)" || vl_soutez == "§68")
                        disable = [false, false, false, false, false];
                    if (vl_soutez == "§10 odst.2 písm. d)" || vl_soutez == "§21 odst.1 písm. d)" || vl_soutez == "§63" || vl_priz_dzr == "d")
                        disable = [false, true, false, false, false];
                    if ((vl_nadTyp == 5 || vl_nadTyp == 6) && (vl_priz_dzr == null || vl_priz_dzr == "")) {
                        if (vl_soutez == "§138")
                            disable = [false, false, true, true, true];
                        else {
                            if (vl_soutez == "§138 kat.")
                                disable = [false, true, false, true, false];
                            else {
                                if (vl_soutez == "§129")
                                    disable = [false, true, true, true, false];
                                else {
                                    if (vl_soutez == "§180" || vl_soutez == "§70")
                                        disable = [false, false, false, false, false];
                                    else
                                        disable = [false, true, false, true, false];
                                }
                            }
                        }
                    }
                    if (pole_s != null && pole_p != null) {
                        for (var i = 0, I = pole_s.length; i < I; i++) {
                            if (pole_p[i] == null)
                                disable[i] = true;
                            if (pole_s[i] != null)
                                disable[i] = true;
                        }
                    }
                    var l_ena = {
                        dat_zad_p_04: !disable[0],
                        dat_kos_p_04: !disable[1],
                        dat_uza_p_04: !disable[2],
                        dat_sml_p_04: !disable[3],
                        dat_real_p_04: !disable[4],
                    };
                    return l_ena;
                }
                PrefabsEvz.NaplnDisable = NaplnDisable;
