var Gordic;
(function (Gordic) {
    var Evz;
    (function (Evz) {
        var WebClient;
        (function (WebClient) {
            /** Visitor komponenty Věcného profilu (Umožňuje rozšířit společný základ) */
            class GEvzVecnyProfilVisitor {
                constructor(opts) {
                    this.dao = opts.dao;
                    this.ixs_pri = opts.ixs_pri;
                    this.readOnly = opts.readOnly;
                }
                //------------------------------------------------------------------
                visit(content) {
                    //console.log("visit from Ada");
                    this.cntSeznam = content;
                    content.setDao(this.dao);
                    content.vpEvents.on("selection", (ctx) => {
                        //console.log("selection z Ada");
                        //this.updateActions(ctx);
                    });
                    content.vpEvents.on("loadseznam", (ctx) => {
                        this.getView().then((view) => { return content.setView(view); });
                    });
                    content.vpEvents.on("enhancegridformat", (ctx) => {
                        ctx.gridFormat.add(this.getGridFormat());
                    });
                    //rozšíření/úprava formuláře při vytváření
                    content.vpEvents.on("enhanceform", (ctx) => {
                        this.enhanceForm(ctx.formDiv, ctx.formDefinition, ctx.dto);
                    });
                    //rozšíření/úprava sesbíraných dat formuláře - do Islu se poté posílá ctx.formData
                    content.vpEvents.on("enhacecollecteddata", (ctx) => {
                        ctx.formData = this.modifyDataBeforeSave(ctx.form, ctx.dto, ctx.formData);
                    });
                    //rozšíření/úprava default profilu gridu
                    content.vpEvents.on("enhancedefaultprofile", (ctx) => {
                        ctx.defaultProfile.columnList = "ixs_pri,cis_vz,znam,ixs_dup_txt,vp_stav_txt,kod_pol,nazev,skp,mat_cis,inv_cis,vyr_cis,mnozstvi,m_vz_sml,m_vz_obj_sml,m_maj,castka,c_vz_sml,c_vz_obj_sml,c_maj,popis,ixs_poz,ucs,nks,nks_zad,duvod_poz,vp_stav ";
                    });
                    content.vpEvents.on("loaddetail", (ctx) => {
                        //console.log("loaddetail - Ada");
                        //console.log(ctx);
                        this.cntDetail = ctx.content;
                        this.updateDetailActions(ctx.dto);
                        this.cntDetail.setStatusBarStav(ctx.dto.vp_stav_txt ?? "Neurčeno");
                    });
                }
                //------------------------------------------------------------------
                getGridFormat() {
                    var gridFormat = new Gordic.Data.GridFormat();
                    gridFormat.addTextColumn({
                        width: 140,
                        name: "ixs_pri",
                        caption: "jres:26600097" //RC 26600097 : Identifikátor VZ
                    })
                        .addNumberColumn({
                        width: 75,
                        name: "cis_vz",
                        caption: "jres:26601103" //RC 26601103 : Pořadí
                    })
                        .addDecimalColumn({
                        width: 120,
                        //name: "m_vz",
                        format: "number(C3)",
                        name: "mnozstvi",
                        caption: "jres:26601104" //RC 26601104 : Počet měrných jedn. VZ
                    })
                        .addCurrencyColumn({
                        width: 140,
                        //                    name: "c_vz",
                        name: "castka",
                        caption: "jres:26601105" //RC 26601105 : Celková částka VZ
                    })
                        .addDecimalColumn({
                        width: 120,
                        name: "m_vz_sml",
                        format: "number(C3)",
                        caption: "jres:26601106" //RC 26601106 : Počet měrných jedn. VZ SML
                    })
                        .addCurrencyColumn({
                        width: 140,
                        name: "c_vz_sml",
                        caption: "jres:26601107" //RC 26601107 : Celková částka VZ SML
                    })
                        .addDecimalColumn({
                        width: 120,
                        name: "m_vz_obj_sml",
                        format: "number(C3)",
                        caption: "jres:26601108" //RC 26601108 : Počet měrných jedn. obj. VZ_SML
                    })
                        .addCurrencyColumn({
                        width: 140,
                        name: "c_vz_obj_sml",
                        caption: "jres:26601109" //RC 26601109 : Celková částka obj. VZ SML
                    });
                    //.addNumberColumn({
                    //    width: 75,
                    //    name: "duvod_poz",
                    //    caption: "jres:26601110" //RC 26601110 : Důvod
                    //})
                    return gridFormat;
                }
                //------------------------------------------------------------------
                updateDetailActions(dto) {
                    const acts = this.cntDetail.actions;
                    acts.actNovy?.updatePermission(dto.Permissions, "lzeNovy");
                    acts.actEvidovat?.updatePermission(dto.Permissions, "lzeEvidovat");
                    acts.actSchvalit?.updatePermission(dto.Permissions, "lzeSchvalit");
                    acts.actStornovat?.updatePermission(dto.Permissions, "lzeStornovat");
                    acts.actZrusitStorno?.updatePermission(dto.Permissions, "lzeZrusitStorno");
                }
                //------------------------------------------------------------------
                getView() {
                    var that = this;
                    return $.Deferred().resolve(new Gordic.Isl.View(this.cntSeznam.isl.Vepsevz.list({ filters: { ixs_pri: this.ixs_pri, readOnly: this.readOnly } }), {
                        onResponse: (data) => {
                            //nastavení servicePermissions
                            if (data.data.length != 0) {
                                if (data.servicePermissions) {
                                    this.cntSeznam.actions.actNovy?.updatePermission(data.servicePermissions, "lzeNovy");
                                    this.cntSeznam.actions.actDetail?.updatePermission(data.servicePermissions, "lzeDetail");
                                    this.cntSeznam.actions.actSchvalit?.updatePermission(data.servicePermissions, "lzeSchvalit");
                                    this.cntSeznam.actions.actStornovat?.updatePermission(data.servicePermissions, "lzeStornovat");
                                    this.cntSeznam.actions.actZrusitStorno?.updatePermission(data.servicePermissions, "lzeZrusitStorno");
                                }
                            }
                            else {
                                var lze = { value: true };
                                var nelze = { value: false, message: "jres:26601111" }; //RC 26601111 : Nenalezen žádný záznam věcného profilu.
                                var perm;
                                //if (!that.readOnly) perm = { lzeNovy: lze, lzeEvidovat: nelze, lzeSchvalit: nelze, lzeStornovat: nelze, lzeZrusitStorno: nelze, lzeDetail: nelze };
                                if (!that.readOnly)
                                    perm = { lzeNovy: lze, lzeEvidovat: nelze, lzeSchvalit: nelze, lzeStornovat: nelze, lzeZrusitStorno: nelze, lzeDetail: nelze };
                                else
                                    perm = { lzeNovy: nelze, lzeEvidovat: nelze, lzeSchvalit: nelze, lzeStornovat: nelze, lzeZrusitStorno: nelze, lzeDetail: nelze };
                                this.cntSeznam.actions.actNovy?.updatePermission(perm, "lzeNovy");
                                this.cntSeznam.actions.actDetail?.updatePermission(perm, "lzeDetail");
                                this.cntSeznam.actions.actSchvalit?.updatePermission(perm, "lzeSchvalit");
                                this.cntSeznam.actions.actStornovat?.updatePermission(perm, "lzeStornovat");
                                this.cntSeznam.actions.actZrusitStorno?.updatePermission(perm, "lzeZrusitStorno");
                            }
                            return data;
                        },
                        key: ["ixs_pri", "cis_vz"],
                        processors: {
                            permissionFragments: new Gordic.Data.FragmentManager(["Permissions.*"])
                        }
                    })).promise();
                }
                //------------------------------------------------------------------
                /**
                 * Rozšíření a upravení formuláře
                 * @param form Div formuláře
                 * @param formDefinition Definice formuláře
                 * @param dto Aktuální dto s daty
                 */
                enhanceForm(form, formDefinition, dto) {
                    var readOnly = dto.vp_stav == 30 || dto.vp_stav == 90;
                    for (let section of formDefinition.form.sections) {
                        switch (section.name) {
                            case "topologie":
                                for (let row of section.rows) {
                                    for (let fieldTyped of row.fields) {
                                        let field = fieldTyped;
                                        switch (field.options.name) {
                                            case "nks":
                                            case "nks_zad":
                                                $.extend(field.options, {
                                                    disabled: readOnly
                                                });
                                                break;
                                        }
                                    }
                                }
                                break;
                            case "intKlasifikace":
                                for (let row of section.rows) {
                                    for (let fieldTyped of row.fields) {
                                        let field = fieldTyped;
                                        switch (field.options.name) {
                                            case "inv_cis":
                                            case "nazev_maj":
                                            case "skupina_id":
                                            case "drh_id":
                                            case "mat_cis":
                                            case "skp":
                                                $.extend(field.options, {
                                                    disabled: readOnly
                                                });
                                        }
                                    }
                                }
                                break;
                            case "popis":
                                for (let row of section.rows) {
                                    for (let fieldTyped of row.fields) {
                                        let field = fieldTyped;
                                        switch (field.options.name) {
                                            case "popis":
                                                $.extend(field.options, {
                                                    disabled: readOnly
                                                });
                                        }
                                    }
                                }
                                break;
                            case "transakce":
                                //úprava políčka množství
                                for (let row of section.rows) {
                                    for (let fieldTyped of row.fields) {
                                        let field = fieldTyped;
                                        switch (field.options.name) {
                                            case "ixs_dup":
                                            case "nazev":
                                            case "mj":
                                            case "mnozstvi":
                                            case "castka":
                                                $.extend(field.options, {
                                                    disabled: readOnly
                                                });
                                        }
                                    }
                                }
                                var newRows = [{
                                        label: "jres:26601106", //RC 26601106 : Počet měrných jedn. VZ SML
                                        fields: [{
                                                widget: "gnumberbox",
                                                extensions: [{ widget: "gnumberbox", options: Gordic.Prefabs.Number.decimal(3, true) }],
                                                options: {
                                                    name: "m_vz_sml",
                                                    disabled: readOnly
                                                }
                                            }]
                                    },
                                    {
                                        label: "jres:26601107", //RC 26601107 : Celková částka VZ SML
                                        fields: [{
                                                widget: "gnumberbox",
                                                extensions: [{ widget: "gnumberbox", options: Gordic.Prefabs.Number.currency() }],
                                                options: {
                                                    name: "c_vz_sml",
                                                    disabled: readOnly
                                                }
                                            }]
                                    }, {
                                        label: "jres:26601108", //RC 26601108 : Počet měrných jedn. obj. VZ_SML
                                        fields: [{
                                                widget: "gnumberbox",
                                                extensions: [{ widget: "gnumberbox", options: Gordic.Prefabs.Number.decimal(3, true) }],
                                                options: {
                                                    name: "m_vz_obj_sml",
                                                    disabled: readOnly
                                                }
                                            }]
                                    }, {
                                        label: "jres:26601109", //RC 26601109 : Celková částka obj. VZ SML
                                        fields: [{
                                                widget: "gnumberbox",
                                                extensions: [{ widget: "gnumberbox", options: Gordic.Prefabs.Number.currency() }],
                                                options: {
                                                    name: "c_vz_obj_sml",
                                                    disabled: readOnly
                                                }
                                            }]
                                    },];
                                section.rows?.push(...newRows);
                                break;
                        }
                    }
                }
                //------------------------------------------------------------------
                /**
                 * Úprava sesbíraných dat z formuláře před uložením
                 * @param form Aktuální formulář
                 * @param dto Aktuální dto
                 * @param formData Sesbíraná data formuláře
                 */
                modifyDataBeforeSave(form, dto, formData) {
                    var row = {};
                    $.extend(true, row, dto);
                    row.ixs_pri = this.ixs_pri;
                    row.cis_vz = dto.cis_vz;
                    row.drh_poz = dto.drh_poz;
                    row.ixs_dup = (formData.ixs_dup?.trim() == "") ? "0000ACA00004" : formData.ixs_dup?.trim();
                    row.nazev = formData.nazev?.trim();
                    row.nazev_skp = formData.nazev_kla?.trim();
                    row.mj = formData.mj?.trim();
                    row.kod_pol = formData.kod_pol;
                    row.mat_cis = formData.mat_cis;
                    row.skp = formData.skp?.trim() ?? "";
                    row.popis = formData.popis?.trim() ?? "";
                    row.skupina_id = formData.skupina_id;
                    row.drh_id = formData.drh_id;
                    row.vyr_cis = formData.vyr_cis;
                    row.nks = formData.nks;
                    row.nks_zad = formData.nks_zad;
                    if (row.nks_zad == null || row.nks_zad?.trim()?.length == 0) {
                        row.nks_zad = row.nks;
                    }
                    row.mnozstvi = formData.mnozstvi;
                    row.castka = formData.castka;
                    row.inv_cis = formData.inv_cis;
                    row.m_vz_sml = formData.m_vz_sml;
                    row.c_vz_sml = formData.c_vz_sml;
                    row.m_vz_obj_sml = formData.m_vz_obj_sml;
                    row.c_vz_obj_sml = formData.c_vz_obj_sml;
                    return row;
                }
            }
            WebClient.GEvzVecnyProfilVisitor = GEvzVecnyProfilVisitor;
        })(WebClient = Evz.WebClient || (Evz.WebClient = {}));
    })(Evz = Gordic.Evz || (Gordic.Evz = {}));
})(Gordic || (Gordic = {}));
