var Gordic;
(function (Gordic) {
    var Evz;
    (function (Evz) {
        var WebClient;
        (function (WebClient) {
            class GVecnyProfilEvzDAO {
                constructor(opts) {
                    this.opts = opts;
                    this.opts = this.opts ?? {};
                }
                //------------------------------------------------------------------
                list(parentContent, dto, opts) {
                    return parentContent.isl.Vepsevz.list({
                        filters: { ixs_pri: this.opts.ixs_pri, readOnly: this.opts.readOnly }
                    }).getData();
                }
                //------------------------------------------------------------------
                evidovat(parentContent, dto, opts) {
                    return parentContent.isl.Vepsevz.upsert({ data: dto }).getData();
                }
                //------------------------------------------------------------------
                schvalit(parentContent, dto, opts) {
                    return parentContent.isl.Vepsevz.schvalit({ data: dto }).getData();
                }
                //------------------------------------------------------------------
                stornovat(parentContent, dto, opts) {
                    return parentContent.isl.Vepsevz.delete({ data: dto }).getData();
                }
                //------------------------------------------------------------------
                zrusitStorno(parentContent, dto, opts) {
                    return parentContent.isl.Vepsevz.undelete({ data: dto }).getData();
                }
                //------------------------------------------------------------------
                hromadnaKontrolaOpravneni(parentContent, dtos, operace, opts) {
                    return parentContent.isl.Vepsevz.checkMassPermissionsBeforeOperation({ dtos: dtos, operace: operace }).get();
                }
                //------------------------------------------------------------------
                hromadnaOperace(parentContent, dtos, operace, opts) {
                    return parentContent.isl.Vepsevz.massOperation({ dtos: dtos, operace: operace }).get();
                }
                //------------------------------------------------------------------
                vytvoritNovouPolozku(parentContent, opts) {
                    return parentContent.isl.Vepsevz.createNewDefaultItem({ ixs_pri: this.opts.ixs_pri }).getData();
                }
                destroy() {
                }
            }
            WebClient.GVecnyProfilEvzDAO = GVecnyProfilEvzDAO;
        })(WebClient = Evz.WebClient || (Evz.WebClient = {}));
    })(Evz = Gordic.Evz || (Gordic.Evz = {}));
})(Gordic || (Gordic = {}));
