Gordic.Previews.register("evz:AllDok", {
    // Ověřování, zda je řádek kompletní
    canRender: function (dto) { return dto.ixp != null; },
    // Samotné vykreslení náhledu
    render: function (div, dto) {
        var currentElement = $(div);
        // data jsou ready -> samotné vytvoření náhledu
        currentElement.empty().append("<h2 class='g-state-text g-state-active' style='margin: 0.5rem;'>Dokument EVZ " + dto.ixp + "</h2><hr style='margin: 0.5rem; opacity: 0.2;'/>");
        Gordic.Previews.displayLinkButton(div, dto);
        var tmp = $("<div class='gform--view-mode'>").appendTo(currentElement)
            .gform("setup", { layoutDescriptor: "L1M1S1, breaks-300-400" }).
            gformsection("create").gpidbar({ pid: dto.ixs_pri }).
            gformsection("create")
            .gformrow("addFieldsRow", "jres:26600090").gformtext(dto.ac_ag === null || dto.ac_ag === undefined ? "" : dto.ac_ag, "bold") //RC 26600090 : Agendové číslo
            .gformrow("addFieldsRow", "jres:26600091").gformtext(dto.ac_ver_zak === null || dto.ac_ver_zak === undefined ? "" : dto.ac_ver_zak, "bold") //RC 26600091 : Evidenční číslo
            .gformrow("addFieldsRow", "jres:26600097").gformtext(dto.ixs_pri === null || dto.ixs_pri === undefined ? "" : dto.ixs_pri, "bold") //RC 26600097 : Identifikátor VZ
            .gformrow("addFieldsRow", "jres:26600134").gformtext(dto.dat_prij_pod === null ? "" : Gordic.Templates.Formatters.date(dto.dat_prij_pod), "bold") //RC 26600134 : Datum evidence
            .gformrow("addFieldsRow", "jres:26600135").gformtext(dto.dat_pis === null ? "" : Gordic.Templates.Formatters.date(dto.dat_pis), "bold") //RC 26600135 : Datum úkonu
            .gformrow("addFieldsRow", "jres:26600100").gformtext(dto.c === null || dto.c === undefined ? "" : dto.c.toString(), "bold") //RC 26600100 : Celková částka
            .gformrow("addFieldsRow", "jres:26600102").gformtext(dto.rezim_pri_txt === null || dto.rezim_pri_txt === undefined ? "" : dto.rezim_pri_txt, "bold"); //RC 26600102 : Režim případu
        currentElement.resize().find(".gform-section").children("label").first().addClass("g-state-text g-state-active");
    }
});
