                //#endregion 
                //---------------------------------------------------------------------
                showComparison(rows) {
                    var that = this;
                    if (rows.length > 0) {
                        var dataRows = rows.map(function (item, idx) { return item.data; }); // převod z grid metadata-view do pole dto
                        if (this.isComparisonInited) {
                            this.addToComparison(dataRows);
                        }
                        else {
                            this.isComparisonInited = true;
                            this.comparisonCnt.empty();
                            this.comparator = $('<div class="js-seznam-comparator">').appendTo(this.comparisonCnt).gcomparator({
                                items: dataRows,
                                columns: that.grid.ggrid("option", "columns"),
                                itemTemplate: "{ixs_pri}",
                                itemchange: function (ev, ctx) {
                                    that.comparisonBadge.value = ctx.count.toString();
                                    that.comparisonBadge.update();
                                },
                                selection: function (ev, ctx) {
                                    that.grid.ggrid("activeRow", ctx.item);
                                }
                            });
                        }
                        for (var row in rows) {
                            rows[row].checked = false;
                        }
                        this.grid.ggrid("refresh");
                    }
                }
                //---------------------------------------------------------------------
                addToComparison(rows) {
                    this.comparator.gcomparator("addItems", rows);
                }
                //---------------------------------------------------------------------
                nastavEnableTlacitek(row) {
                    //if (row) this.actions.actPodani!.enabled((row.vlastnik! || this.paramGvycza == 1) && this.ap.podani!);
                    var l_lze = row != null && row.s_vz != 99;
                    this.actions.actPodani.enabled((row != null && row.vlastnik || this.paramGvycza == 1) && this.ap.podani && l_lze);
                    this.actions.actNavrhy.enabled(l_lze);
                }
                //---------------------------------------------------------------------
                detail() {
                    var that = this;
                    var row = this.grid.ggrid("activeRow");
                    that.isl.EvzVerejnaZakazka.read({
                        data: { ixs_pri: row.ixs_pri },
                        fragments: ["common", "detail", "minimum", "foreach"]
                    })
                        .getData()
                        .then(function (detail) {
                        var def0 = $.Deferred();
                        if (detail.soutez == "§138 kat." && detail.ixs_pri_nad != null && detail.dotaz_frs) {
                            that.dotaz("jres:26601056") //RC 26601056 : Nadřízená veřejná zakázka (DNS) má definované nové uchazeče.;;Bude provedena kontrola jejich zařazení pro VZ v DNS;včetně kontroly na napojené Kategorie.;;V případně splnění podmínek bude nabídnuta možnost doplnění do této VZ.
                                .then(() => {
                                var l_dotaz = "jres:26601115"; //RC 26601115 : Chcete doplnit tento subjekt do VZ?;
                                let arr = [];
                                var l_pocet = 0;
                                for (let i = 0; i < detail.dataFrs.length; i++) {
                                    arr.push(that.dotaz(l_dotaz + detail.dataFrs[i].ixs_esu + "/" + detail.dataFrs[i].ixs_esu_txt)
                                        .then(() => {
                                        l_pocet++;
                                        return that.isl.EvzDetailVZ.obsluzInitDataFrs({ param: detail.dataFrs[i] }).get();
                                    }));
                                }
                                $.when.apply(null, arr).always(() => {
                                    detail.evzsesuCount += l_pocet;
                                    def0.resolve();
                                });
                            })
                                .fail(function () { def0.resolve(); });
                        }
                        else
                            def0.resolve();
                        def0.then(() => {
                            var newGpc = Gordic.Eko.Utils.createBookGpc(that.gpc, row.ixp_den);
                            var detailContent = that.navigate(["Gordic.Evz.WebClient.GEvzDetailVZ", {
                                    gridRemoteControl: new Gordic.Components.GridRC(that.grid), gpc: newGpc
                                }], {
                                taskId: "actGEvzSeznamScr", data: detail,
                                uid: "GEvzDetailVZ#"
                            });
                            detailContent.on("close", function (ev, ctx) {
                                if (ev.target === detailContent.get(0) && ctx && ctx.isChanged) {
                                    that.obnovSeznam();
                                }
                                else
                                    detailContent.one('closed', function () {
                                        if (that.grid.hasClass('ggrid')) {
                                            that.grid.ggrid('focus');
                                        }
                                    });
                            });
                        }).done(() => { });
                    });
                }
                //---------------------------------------------------------------------
                nastavTlacitka() {
                    var isBookSelected = Gordic.Eko.Utils.getEkoBookVariant(this) === 1 /* Eko.Interface.GEkoBookVariant.One */ ? true : false; // pokud je toto false, jsou vybrané všechny knihy/knihy za rok/není kniha
                    var enabledProhl = this.view.getCount("filter") > 0;
                    var enabled = enabledProhl && this.evz_rad_poupro != "1";
                    this.actions.actNovyVZ.enabled(this.ap.podani && isBookSelected && this.evz_rad_oldsvz != "0" && this.evz_rad_poupro != "1");
                    this.actions.actDetailVZ.enabled(enabledProhl);
                    this.actions.actNavrhy.enabled(enabled);
                    this.actions.actUkony.enabled(enabledProhl);
                    this.actions.actPodani.enabled(enabled && this.ap.podani);
                    this.actions.actNavrhy.enabled(enabled && this.ap.generuj_sml);
                    this.actions.actUzavreni.enabled(enabled);
                    this.actions.actUzavreniZrusit.enabled(enabled);
                    this.actions.actUkonceni.enabled(enabled);
                    this.actions.actUkonceniZrusit.enabled(enabled);
                    this.actions.actUvolneni.enabled(enabled && this.ap.uvolneni);
                    this.actions.actPreevidence.enabled(enabled && this.ap.preevidence);
                    this.actions.actPredani.enabled(enabled && this.ap.predani);
                    this.actions.actPrevzeti.enabled(enabled && this.ap.prevzeti);
                    this.actions.actPrideleni.enabled(enabled && this.ap.prideleni);
                    this.actions.actKlicovaSlova.enabled(enabled);
                    this.actions.actTisky.enabled(enabled);
                    this.actions.actHFK.enabled(enabled);
                    this.actions.actExportRza.enabled(enabled && this.exportDoRzaEnabled);
                    //      this.actions.actVS!.enabled(enabled);
                }
