                //---------------------------------------------------------------------
                dotaz(otazka) {
                    return this.dialogs.confirm(otazka).createDialogPromise("yes");
                }
                //---------------------------------------------------------------------
                vratData() {
                    var seznam = this.grid.ggrid("getSelection");
                    var blok = [];
                    for (var i = 0, I = seznam.length; i < I; i++) {
                        blok.push({
                            identifikator: seznam[i].ixs_pri, cislo: seznam[i].cis_zakon, cisloDec: null, datum: null,
                            stav: seznam[i].s_vz, ac: seznam[i].ac_ver_zak, ac_ag: seznam[i].ac_ag, nazev: seznam[i].nazev,
                            stav_txt: seznam[i].s_vz_txt, vlastnik: seznam[i].vlastnik_nazev, ixp_den: seznam[i].ixp_den, ixp_den_txt: seznam[i].ixp_den_nazev, vlastnikIdent: seznam[i].vlastnikIdent
                        });
                    }
                    return blok;
                }
                //---------------------------------------------------------------------
                dotazAnoNe(titulek, otazka) {
                    return this.dialogs.confirm(titulek, otazka).createDialogPromise(["yes", "no"]);
                }
