                        if (data.dotaz != "") { // došel nějaký dotaz
                            def1 = that.dotazAnoNe("jres:26601097", data.dotaz).then((par1) => {
                                if (par1 === "yes")
                                    ktg_typ = data.ktgAno;
                                else
                                    ktg_typ = data.ktgNe;
                                return;
                            });
                        }
