                        Gordic.Evz.Dialogs.GEvzPodani(that, { genIxp: that.genIxp, ixp: null, ktg_typ: ktg_typ, ele: false, ixs_krk: null, modOkna: "new", ixs_pri: null, allDok: true, ac_ag: null, soutez: null, ixs_esu: "", por_cis_nab: -1, novaVZ: true })
