                    Gordic.Evz.Dialogs.GEvzPodani(that, {
                        genIxp: this.genIxp, ixp: null, ktg_typ: radek !== undefined ? radek.ktg_typ : null, ele: ele, ixs_krk: "",
                        modOkna: "new", ixs_pri: radek !== undefined ? radek.ixs_pri : null, allDok: true, ac_ag: radek !== undefined ? radek.ac_ag : null,
                        soutez: radek !== undefined ? radek.soutez : null, ixs_esu: "", por_cis_nab: -1, novaVZ: false
                    })
