                            serverParameterMethod: "Gordic.Evz.WebClient.GEvzPrintParameters:ServerParameterMethodTiskSeznamDok",
                            serverRestrictionAlvMethod: "Gordic.Evz.WebClient.GEvzPrintParameters:GetRestrictionAlf",
