                        //    if (ctx != null && ctx.cellInfo != null && ctx.cellInfo.data != null) {
                        //        that.previewController.enable(true);
                        //        that.previewController.show(ctx.cellInfo.data);
                        //    } else {
                        //        that.previewController.enable(false);
                        //    }
                        //},
                        selection: function (ev, obj) {
                            if ($(this).hasClass('ggrid')) {
                                if (that.previewController) {
                                    var meta = $(this).ggrid('activeRow', true);
                                    if (meta && meta.data && meta._isVirtual !== true) {
                                        that.previewController.enable(true);
                                        that.previewController.show(meta.data);
                                    }
                                    else {
                                        that.previewController.enable(false);
                                    }
                                }
                            }
                        },
                        defaultProfile: {
                            condFormats: Gordic.Pap.WebControls.vytvorSeznamPriDokParamPF({ agenda: "evz", pole: "" }),
                            columnList: l_columnList
                        },
                        profiles: [
                            { name: "Úplný", columnList: l_columnListFull, condFormats: Gordic.Pap.WebControls.vytvorSeznamPriDokParamPF({ agenda: "evz", pole: "" }), _locked: true },
                            { name: "Barevný", columnList: l_columnList, condFormats: Gordic.Pap.WebControls.vytvorSeznamPriDokParamPF({ agenda: "evz", pole: l_columnList }), _locked: true },
                            { name: "Zjednodušený", columnList: l_columnListShort, condFormats: Gordic.Pap.WebControls.vytvorSeznamPriDokParamPF({ agenda: "evz", pole: "" }), _locked: true },
                        ],
                        //searchColumns: ["ixp"], //sloupce, podle kterych se vyhledava v searchboxu
                        columns: gridcolumns,
