                //---------------------------------------------------------------------
                akceEpk() {
                    var that = this;
                    var radek = this.grid.ggrid("getSelection")[0];
                    var opt = {
                        Ixp: radek.ixp
                    };
                    Gordic.Wfl.Dialogs.GSchvalovaciProcesPozadavekDlg(this, opt, Gordic.Gin.Globals.Enums.ModOtevreni.navigate)
                        .done(function (retval) {
                        if (retval && retval.stav) {
                            that.obnovSeznam();
                        }
                    });
                }
                //---------------------------------------------------------------------
                obnovSeznam() {
                    if (this.refreshData)
                        this.view.requestData();
                }
                //---------------------------------------------------------------------
                akcePodani(ele) {
                    var that = this;
                    var row = this.grid.ggrid("getSelection")[0];
                    Gordic.Evz.Dialogs.GEvzPodani(this, { genIxp: this.genIxp, ixp: null, ktg_typ: row.ktg_typ, ele: false, ixs_krk: null, modOkna: "new", ixs_pri: row.ixs_pri, allDok: false, ac_ag: row.ac_ag, soutez: row.soutez, ixs_esu: "", por_cis_nab: -1, novaVZ: false })
                        .then(function (retval) {
                        var detailContent = that.navigate("Gordic.Evz.WebClient.GEvzDetail", {
                            taskId: that.task_id,
                            uid: "GEvzDetail#",
                            ixp: retval.ixp, ktg_typ: retval.ktg_typ, ele: false, ixs_krk: retval.ixs_krk, modOkna: "newEdit", ixs_pri: retval.ixs_pri, podaniOut: false, allDok: true, ac_ag: null, soutez: retval.soutez, ixs_esu: ""
                        });
                        detailContent.on("close", function (ev, ctx) {
                            if (ev.target === detailContent.get(0) && ctx && ctx.isChanged) {
                                var focusFunc = function () {
                                    if (that.grid.hasClass('ggrid')) {
                                        that.grid.ggrid('focus'); // nastavení focusu na grid
                                        that.view.off('change.focus', focusFunc); // odvázání události z ISL view
                                    }
                                };
                                that.view.on('change.focus', focusFunc);
                                that.obnovSeznam();
                            }
                            else
                                detailContent.one('closed', function () { if (that.grid.hasClass('ggrid'))
                                    that.grid.ggrid('focus'); });
                        });
                    });
                }
                //---------------------------------------------------------------------
                getOpenDetailDelegate() {
                    var that = this;
                    var seznam = this.view.getDataRows();
                    return (cnt, grid, row) => {
                        var rowSez = {};
                        for (let i = 0, ii = seznam.length; i < ii; i++) {
                            if (seznam[i].ixp === row.identifikator) {
                                rowSez = seznam[i];
                                break;
                            }
                        }
                        let gridRC = new Gordic.Components.GridRC(grid); //pohyb po gridu
                        var detailContent = cnt.navigate(["Gordic.Evz.WebClient.GEvzDetail", {
                                gridRemoteControl: gridRC
                            }], {
                            taskId: that.task_id,
                            uid: "GEvzDetail#",
                            ixs_pri: rowSez.ixs_pri, modOkna: "edit", ele: false, ixp: rowSez.ixp, ixs_krk: rowSez.ixs_krk, ktg_typ: rowSez.ktg_typ, ac_ag: rowSez.ac_ag, allDok: false, soutez: rowSez.soutez, ixs_esu: ""
                        });
                    };
                }
                //---------------------------------------------------------------------
                getOpenDetailDelegateEvz() {
                    var that = this;
                    var seznam = this.view.getDataRows();
                    return (cnt, grid, row) => {
                        let gridRC = new Gordic.Components.GridRC(grid); //pohyb po gridu
                        var detailContent = cnt.navigate(["Gordic.Evz.WebClient.GEvzDetail", {
                                gridRemoteControl: gridRC
                            }], {
                            taskId: that.task_id,
                            uid: "GEvzDetail#",
                            ixs_pri: row.ixs_pri, modOkna: "edit", ele: false, ixp: row.ixp, ixs_krk: row.ixs_krk, ktg_typ: row.ktg_typ, ac_ag: row.ac_ag, allDok: false, soutez: row.soutez, ixs_esu: ""
                        });
                    };
                }
                //---------------------------------------------------------------------
                akceDetail() {
                    var that = this;
                    var row = this.grid.ggrid("activeRow");
                    var mod = row.evz_stav == 10 ? "newEdit" : "edit";
                    var detailContent = this.navigate(["Gordic.Evz.WebClient.GEvzDetail", {
                            gridRemoteControl: new Gordic.Components.GridRC(that.grid)
                        }], {
                        taskId: that.task_id,
                        uid: "GEvzDetail#",
                        ixs_pri: row.ixs_pri, modOkna: mod, ele: false, ixp: row.ixp, ixs_krk: row.ixs_krk, ktg_typ: row.ktg_typ, ac_ag: row.ac_ag, allDok: false, soutez: row.soutez, ixs_esu: ""
                    }); //zobrazeni dalsiho detailu - stejne okno
                    detailContent.on("close", function (ev, ctx) {
                        if (ev.target === detailContent.get(0) && ctx && ctx.isChanged) {
                            var focusFunc = function () {
                                if (that.grid.hasClass('ggrid')) {
                                    that.grid.ggrid('focus'); // nastavení focusu na grid
                                    that.view.off('change.focus', focusFunc); // odvázání události z ISL view
                                }
                            };
                            that.view.on('change.focus', focusFunc);
                            that.isChanged = true;
                            that.obnovSeznam();
                        }
                        else
                            detailContent.one('closed', function () {
                                if (that.grid.hasClass('ggrid'))
                                    that.grid.ggrid('focus');
                            });
                    });
                }
                //---------------------------------------------------------------------
                akceSchvalitPis(storno) {
                    var that = this;
                    var blok = this.grid.ggrid("getSelection");
                    this.dotaz("jres:26600552", storno ? "jres:26600798" : "jres:26600553") //RC 26600798 : Opravdu chcete hromadné odschválení označených dokumentů?
                        .then(function () {
                        Gordic.Evz.WebClient.EvzPrefabsAll.SchvalitPis({
                            parentContent: that,
                            data: that.grid.ggrid("getSelection"),
                            zrusit: storno,
                            completeDelegate: (view) => {
                                that.obnovSeznam();
                            },
                            allDok: false,
                            openDetailDelegate: that.getOpenDetailDelegateEvz()
                        });
                    });
                }
                //---------------------------------------------------------------------
                dotaz(titulek, otazka) {
                    return this.dialogs.confirm(titulek, otazka).createDialogPromise("yes");
                }
                //---------------------------------------------------------------------
                akcePripominka() {
                }
                //---------------------------------------------------------------------
                nastavTlacitka() {
                    var enabled = false;
                    var enabledAct = this.view.getCount("filter") > 0;
                    if (enabledAct) {
                        var row = this.grid.ggrid("activeRow");
                        enabled = enabledAct && this.evz_rad_poupro != "1" && row.s_vz != 99;
                    }
                    else
                        enabled = enabledAct;
                    this.actions.actPodani.enabled(enabled && this.ap.podani);
                    this.actions.actPodaniEl.enabled(enabled && this.ap.podaniel);
                    this.actions.actDetail.enabled(enabledAct && this.ap.detail);
                    this.actions.actSchvalitPis.enabled(enabled && this.ap.schvalit);
                    this.actions.actOdSchvalitPis.enabled(enabled && this.ap.schvalit);
                    //this.actions.actPredvyhodn!.enabled(enabled && this.ap.predvyhodnoceni!);
                    //this.actions.actNavrhy!.enabled(enabled && this.ap.predvyhodnoceni!);
                    //this.actions.actPredaniPis!.enabled(enabled && this.ap.predani_pis!);
                    //this.actions.actPredaniVlapis!.enabled(enabled && this.ap.predani_vlapis!);
                    this.actions.actPredani.enabled(enabled && this.ap.predani);
                    this.actions.actPrideleni.enabled(enabled && this.ap.prideleni);
                    this.actions.actPrevzeti.enabled(enabled && this.ap.prevzeti);
                    //this.actions.actPreevidEsu!.enabled(enabled && this.ap.preevid_esu!);
                    //this.actions.actZamenEsu!.enabled(enabled && this.ap.zamen_esu!);
                    this.actions.actUkonceni.enabled(enabled && this.ap.ukonceni);
                    this.actions.actUkonceniZrus.enabled(enabled && this.ap.ukonceni_zrus);
                    this.actions.actStornoPis.enabled(enabled && this.ap.stornopis);
                    this.actions.actStornoPisZrus.enabled(enabled && this.ap.stornopis);
                    this.actions.actGenerovaniDok.enabled(enabled /*nevím*/);
                    this.actions.actTisky.enabled(enabled);
                    this.actions.actKontrolaMetadat.enabled(enabled);
                }
